/* ------------------------------------------------------------------ */
/* Data                                                                */
/* ------------------------------------------------------------------ */

export type PaperStamp = { text: string; date?: string; color?: string }

type SheetBase = {
  /** Accessible name of the ball, e.g. "Letter from June". Derived when omitted. */
  label?: string
  /** Paper colour of the sheet. */
  paper?: string
}

export type LetterSheet = SheetBase & {
  kind: "letter"
  date?: string
  greeting?: string
  body: string[]
  closing?: string
  signature?: string
  /** Ink colour, default a blue-black fountain-pen ink. */
  ink?: string
}

export type PhotoSheet = SheetBase & {
  kind: "photo"
  /** Image URL or data URI. Remote images need CORS headers. */
  image?: string
  alt?: string
  caption?: string
  date?: string
}

export type TypedSheet = SheetBase & {
  kind: "typed"
  letterhead: string
  tagline?: string
  date?: string
  greeting?: string
  body: string[]
  closing?: string
  signature?: string
  signer?: string
  stamp?: PaperStamp
}

export type PaperSheet = LetterSheet | PhotoSheet | TypedSheet

export interface CrumpledPaperRevealProps {
  /** One crumpled ball per sheet, in order. */
  sheets?: PaperSheet[]
  /** Definite height of the stage. Never inherited. */
  height?: string
  /** Small line under the balls; false hides it. */
  hint?: string | false
  className?: string
}

